import {motion} from "framer-motion";
import {Grid} from "@mui/material";
import LinearProgressWithColorWave
    from "../../constants/linearProgress";
import LinearProgressWithWaveColor
    from "../../constants/linearProgress";

const Skills = () => {
    return (
        <>
            <motion.div initial={{y: "20vh", opacity: 0 }}
                        whileInView={{y: 0,opacity: 1}}
                        w
                        transition={{duration: 0.5}}>
                <Grid container
                      sx={{
                          justifyContent: "space-around",
                          pr: 1,
                          color:"#a8a8a8"
                      }}
                >
                    <Grid size={{xs: 12, md: 6}}
                          sx={{my: "1.5rem"}}>
                        <LinearProgressWithColorWave value={60}
                                                     label="js"/>
                    </Grid>
                    <Grid size={{xs: 12, md: 6}}
                          sx={{my: "1.5rem"}}>
                        <LinearProgressWithColorWave value={70}
                                                     label="python"/>
                    </Grid>
                    <Grid size={{xs: 12, md: 6}}
                          sx={{my: "1.5rem"}}>
                        <LinearProgressWithColorWave value={70}
                                                     label="react"/>
                    </Grid>
                    <Grid size={{xs: 12, md: 6}}
                          sx={{my: "1.5rem"}}>

                        <LinearProgressWithColorWave value={70}
                                                     label="django"/>
                    </Grid>
                    <Grid size={{xs: 12, md: 6}}
                          sx={{my: "1.5rem"}}>
                        <LinearProgressWithColorWave value={95}
                                                     label="html"/>
                    </Grid>
                    <Grid size={{xs: 12, md: 6}}
                          sx={{my: "1.5rem"}}>
                        <LinearProgressWithColorWave value={90}
                                                     label="css"/>
                    </Grid>

                    <Grid size={{xs: 12, md: 6}}
                          sx={{my: "1.5rem"}}>
                        <LinearProgressWithWaveColor value={90}
                                                     label="bootstrap"/>
                    </Grid>
                    <Grid size={{xs: 12, md: 6}}
                          sx={{my: "1.5rem"}}>
                        <LinearProgressWithColorWave value={20}
                                                     label="api"/>
                    </Grid>
                </Grid>
            </motion.div>
        </>
    );
};

export default Skills;