import {Box, Typography} from "@mui/material";

const AboutMeBG = () => {
    return (
        <>
            <Box sx={{
                display: "flex",
                justifyContent: "center"
            }}>
                <Typography
                    sx={{
                        opacity: 0.1,
                        textAlign: "center",
                        position: "absolute",
                        fontSize: '7rem',
                        fontWeight: 'bold',
                        background: 'linear-gradient(to right, #b4b4b4, #4B4B4BFF, #b4b4b4)',
                        backgroundSize: '200% auto',
                        backgroundClip: 'text',
                        WebkitBackgroundClip: 'text',
                        color: 'transparent',
                        zIndex: 1,
                        WebkitTextFillColor: 'transparent',
                        animation: 'wave 4s linear' + ' infinite',
                        '@keyframes wave': {
                            '0%': {
                                backgroundPosition: '200% center',
                            }, '100%': {
                                backgroundPosition: '0% center',
                            },
                        },
                    }}>
                    About Me
                </Typography>
            </Box>
        </>
    )
}

export default AboutMeBG;