import {Box} from "@mui/material";
import scroll from "../../assets/scrollDown.gif";

const Scroll = ({sx}) => {
    return (
        <Box sx={{display:"flex" , justifyContent:"center" , ...sx}}>
            <Box>
                <img  src={scroll} alt="scroll" />
                <img  src={scroll} alt="scroll"/>
            </Box>
        </Box>
    )
}

export default Scroll;