import {motion} from "framer-motion";
import {Box, Typography} from "@mui/material";
import {useEffect, useRef} from "react";
import Typed from "typed.js";

const HomeContent = () => {

    const nameEl = useRef(null);
    const infoEl = useRef(null);

    const strings = [
        "IM PROGRAMMER",
        "IM EDITOR",
        "IM DESIGNER"
    ];

    useEffect(() => {
        const typedName = new Typed(nameEl.current, {
            strings: [" Hossein Nekouie "],
            typeSpeed: 120,
            backSpeed: 20,
            backDelay: 10,
            showCursor: false,
        });

        const typedInfo = new Typed(infoEl.current, {
            strings: strings,
            startDelay: 3000,
            typeSpeed: 80,
            backSpeed: 50,
            backDelay: 50,
            loop: true,
            showCursor: false,
        });

        return () => {
            typedName.destroy();
            typedInfo.destroy();
        };
    }, []);

    return (
        <Box sx={{height: "20%"}}>
            <motion.div
                initial={{opacity: 0, y: "-50vh"}}
                animate={{opacity: 1, y: 0}}
                transition={{duration: 1, ease: "easeInOut"}}>
                <Typography ref={nameEl}
                            variant="h4"
                            fontFamily="Bebas Neue"
                            fontSize="4rem"
                            sx={{
                                color: "#000000",
                                position: "sticky",
                                zIndex: 2,
                            }}></Typography>

            </motion.div>
            <Typography
                ref={infoEl}
                variant="subtitle1"
                sx={{fontWeight: "bold"}}
            ></Typography>
        </Box>
    )
}

export default HomeContent;