import {Box, Button, Grid, Link, TextField, Typography} from "@mui/material";
import {GitHub, Instagram, Telegram} from "@mui/icons-material";


const Contact = () => {
    return (
        <Grid container sx={{
            display: 'flex',
            justifyContent: "center",
            alignItems: "center",
            flexDirection: "column",
            width: '100%',
        }}>
            <Grid sx={{
                display: "flex", justifyContent: "center",
                flexDirection: "column",
                alignItems: "center",
                mt: 3,
                mb: 6
            }}>
                <Typography variant="h3">ارتباط با من</Typography>
                <Typography variant="subtitle1">
                    خوشحال می‌شم اگر پیشنهادی، سوالی یا پروژه‌ای دارید، با من در ارتباط باشید.
                </Typography>
            </Grid>
            <Grid sx={{
                display: "flex", justifyContent: "center",
                flexDirection: "column", width: "60%",
            }}>
                <form style={{
                    display: "flex", justifyContent: "center", flexDirection: "column"
                }}>
                    <TextField sx={{mb: "2rem"}} id="outlined-basic" label="نام شما"
                               variant="outlined"/>
                    <TextField sx={{mb: "2rem"}} id="outlined-basic" label="ایمیل شما" type="email"
                    />
                    <TextField sx={{mb: "2rem"}} id="outlined-basic" label="پیام شما"
                    ></TextField>
                    <Button type={"submit"} variant="contained">ارسال</Button>
                </form>
            </Grid>
            <Box sx={{width: "50%", display: "flex", justifyContent: "space-around", mt: "5rem"}}>
                <Link href="https://t.me/hosseinngh81">
                    <Telegram/>
                </Link>
                <Link href="https://github.com/Nekouie">
                    <GitHub/>
                </Link>
                <Link href="https://www.instagram.com/hossein.nki?igsh=cTJiMTgzOHg5Y2t2">
                    <Instagram/>
                </Link>
            </Box>
        </Grid>
    );
};

export default Contact;
