import {Container, Divider, Paper, Typography} from "@mui/material";
import {motion} from "framer-motion";

const Description = () => {
    return (
        <>
            <motion.div initial={{y: "-5vh", opacity: 0 , rotateX:"120deg"}}
                        whileInView={{y: 0, opacity: 1, rotateX: 0}}
                        transition={{duration: 0.5}}>
                <Container maxWidth="md">
                    <Paper elevation={3} sx={{p: 4, mt: 8}}>
                        <Typography variant="h4" gutterBottom>About
                            Me</Typography>
                        <Typography variant="body1" paragraph>
                            Hi! I'm Hossein Nekooei, a
                            frontend
                            web enthusiast with a passion for
                            clean and professional UI design.
                            I've completed courses in HTML,
                            CSS,
                            Bootstrap, React, and MUI, and I
                            really enjoy building sleek and
                            user-friendly interfaces.
                        </Typography>
                        <Typography variant="body1" paragraph>
                            Currently, I'm working on personal
                            projects to strengthen my skills
                            and
                            looking for an opportunity to
                            enter
                            the job market.
                        </Typography>

                        <Typography variant="h6"
                                    sx={{mt: 3}}>Skills
                            :</Typography>
                    </Paper>
                </Container>
            </motion.div>


        </>
    )
}

export default Description;