import {
    Divider, Grid,
} from "@mui/material";
import {AboutUsHeader, Skills, Description, Scroll, AboutMeBG} from "./aboutMe/";

const AboutMe = () => {

    return (
        <Grid
            container
            spacing={2}
            sx={{
                display: "flex",
                justifyContent: "space-around",
                overflowY: "scroll",
                backgroundColor: "#252525",
                height: "100%",
            }}
        >
            <Grid>
                <AboutMeBG/>
                <AboutUsHeader/>
                <Divider sx={{marginTop: "4rem", color: "#ffffff"}}/>
                <Description/>

                <Scroll/>

                <Skills/>

            </Grid>
        </Grid>
    )
}

export default AboutMe;